chcp 65001 >nul
echo ========================================
echo  修复 Git Bash PATH 环境
echo ========================================
echo.

set "GIT_BASH_PATH=C:\Users\songa\AppData\Local\GitHubDesktop\app-3.5.4\resources\app\git\usr\bin"
set "GIT_BIN_PATH=C:\Users\songa\AppData\Local\GitHubDesktop\app-3.5.4\resources\app\git\bin"

echo [1/3] 检查 Git Bash 是否存在...
if exist "%GIT_BASH_PATH%\sh.exe" (
    echo   ✅ 找到 sh.exe: %GIT_BASH_PATH%\sh.exe
) else (
    echo   ❌ 未找到 sh.exe！
    pause
    exit /b 1
)

echo.
echo [2/3] 当前系统 PATH 中是否已包含 Git Bash...
echo %PATH% | findstr /i "GitHubDesktop.*git" >nul
if %errorlevel%==0 (
    echo   ⚠️ Git Bash 已在 PATH 中，但可能优先级不对
) else (
    echo   ❌ Git Bash 不在 PATH 中
)

echo.
echo [3/3] 添加到当前用户 PATH...

REM 使用 setx 永久添加到用户环境变量
for /f "skip=2 tokens=3*" %%a in ('reg query "HKCU\Environment" /v PATH 2^>nul') do set "CURRENT_PATH=%%b"
if "%CURRENT_PATH%"=="" set "CURRENT_PATH="

REM 检查是否已存在
echo %CURRENT_PATH% | findstr /i "GitHubDesktop.*git.*usr.*bin" >nul
if %errorlevel%==0 (
