499	function switchMethod(method) {
500	    currentMethod = method;
501	    document.querySelectorAll(".controls button").forEach(b => {
502	        if (b.textContent.includes("Z-score") || b.textContent.includes("简易公式")) {
503	            const isZ = b.textContent.includes("Z-score");
504	            b.className = (isZ && method === "zscore") || (!isZ && method === "simple") ? "active" : "";
505	        }
506	    });
507	    renderAll();
508	}
509	
510	function switchView(view) {
511	    currentView = view;
512	    document.getElementById("btn-lane").className = view === "lane" ? "active" : "";
513	    document.getElementById("btn-global").className = view === "global" ? "active" : "";
514	    if (view === "lane") {
515	        currentLane = currentLane || Object.keys(computedData.lanes)[0];
516	        document.querySelectorAll("#nav button").forEach(b => {
517	            b.className = b.textContent === currentLane ? "active" : "";
518	        });
519	    } else {
520	        document.querySelectorAll("#nav button").forEach(b => b.className = "");
521	    }
522	    renderAll();
523	}
524	
525	function buildNav() {
526	    const nav = document.getElementById("nav");
527	    nav.innerHTML = "";
528	    Object.keys(computedData.lanes).forEach(lane => {
529	        const btn = document.createElement("button");
530	        btn.textContent = lane;
531	        btn.className = lane === currentLane ? "active" : "";
532	        btn.onclick = () => {
533	            currentLane = lane;
534	            switchView("lane");
535	        };
536	        nav.appendChild(btn);
537	    });
538	}
539	
540	function renderAll() {
541	    if (!computedData) return;
542	    const content = document.getElementById("content");
543	    if (currentView === "global") {
544	        content.innerHTML = renderGlobalView();
545	    } else {
546	        content.innerHTML = renderLaneView(currentLane);
547	    }
548	}
549	
550	// ============================================================
551	// 搜索
552	// ============================================================
553	function doSearch(query) {
554	    if (!query || query.trim().length === 0) {
555	        renderAll();
556	        return;
557	    }
558	    const q = query.trim().toLowerCase();
559	    const results = [];
560	    for (const heroes of Object.values(computedData.lanes)) {
561	        for (const h of heroes) {
562	            if (h.name.toLowerCase().includes(q)) {
563	                results.push(h);
564	            }
565	        }
566	    }
567	
568	    // 在分路视图显示搜索结果
569	    currentView = "lane";
570	    document.getElementById("btn-lane").className = "active";
571	    document.getElementById("btn-global").className = "";
572	    document.querySelectorAll("#nav button").forEach(b => b.className = "");
573	
574	    if (results.length === 0) {
575	        document.getElementById("content").innerHTML = `<p style="text-align:center;padding:40px;color:#8b949e;">未找到匹配 "${query}" 的英雄</p>`;
576	        return;
577	    }
578	
579	    const scoreKey = getScoreKey();
580	    const tierKey = getTierKey();
581	    const rankKey = getRankKey();
582	    const globalRankKey = getGlobalRankKey();
583	
584	    let html = `<div class="lane-header"><h2>🔍 搜索结果："${query}"</h2><span class="hero-count">${results.length} 个英雄</span></div>
585	    <div class="table-wrapper"><table>
586	        <thead><tr>
587	            <th>分路排名</th><th>英雄</th><th>分路</th><th>梯度</th><th>评分</th>
588	            <th>胜率</th><th>出场率</th><th>Ban率</th><th>BP率</th><th>全局排名</th>
589	        </tr></thead><tbody>`;
590	
591	    results.sort((a, b) => b[scoreKey] - a[scoreKey]).forEach(h => {
592	        html += `<tr>
593	            <td class="rank-num ${getRankClass(h[rankKey])}">${h[rankKey]}</td>
594	            <td class="hero-name">${h.name}</td>
595	            <td style="color:#8b949e">${h.lane}</td>
596	            <td>${getTierBadge(h[tierKey])}</td>
597	            <td>${getScoreBar(h[scoreKey], h[tierKey])}</td>
598	            <td class="${getWrClass(h.wr * 100)}">${(h.wr * 100).toFixed(2)}%</td>
599	            <td>${(h.pr * 100).toFixed(2)}%</td>
600	            <td>${(h.br * 100).toFixed(2)}%</td>
601	            <td>${(h.bp * 100).toFixed(2)}%</td>
602	            <td style="color:#8b949e">#${h[globalRankKey]}</td>
603	        </tr>`;
604	    });
605	    html += `</tbody></table></div>`;
606	    document.getElementById("content").innerHTML = html;
607	}
608	
609	// ============================================================
610	// 表格排序
611	// ============================================================
612	function sortLaneTable(th, colIdx) {
613	    const table = th.closest("table");
614	    const tbody = table.querySelector("tbody");
615	    const rows = Array.from(tbody.querySelectorAll("tr"));
616	    const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
617	
618	    table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
619	    th.classList.add("sorted");
620	    if (isDesc) th.classList.add("desc");
621	
622	    rows.sort((a, b) => {
623	        let va = a.cells[colIdx].textContent.replace(/[#%]/g, "").trim();
624	        let vb = b.cells[colIdx].textContent.replace(/[#%]/g, "").trim();
625	
626	        if (colIdx === 2) {
627	            va = TIER_ORDER.indexOf(va);
628	            vb = TIER_ORDER.indexOf(vb);
629	        }
630	        const na = parseFloat(va);
631	        const nb = parseFloat(vb);
632	        if (!isNaN(na) && !isNaN(nb)) {
633	            return isDesc ? nb - na : na - nb;
634	        }
635	        return isDesc ? vb.localeCompare(va) : va.localeCompare(vb);
636	    });
637	    rows.forEach(r => tbody.appendChild(r));
638	}
639	
640	function sortGlobalTable(th, colIdx) {
641	    sortLaneTable(th, colIdx);
642	}
643	
644	// ============================================================
645	// 启动
646	// ============================================================
647	async function init() {
648	    await loadData();
649	    computeAll();
650	    currentLane = Object.keys(computedData.lanes)[0];
651	    buildNav();
652	    switchView("lane");
653	}
654	
655	init();
656	</script>
657	
658	</body>
659	</html>

