function parsePct(s) { return parseFloat(String(s).replace('%','')) / 100; }
function mean(arr) { return arr.reduce((a,b) => a+b, 0) / arr.length; }
function stdDev(arr) { const m = mean(arr); const v = arr.reduce((s,v) => s + (v-m)**2, 0) / arr.length; return Math.sqrt(v) || 1; }
function zScores(arr) { const m = mean(arr); const s = stdDev(arr); if (s===0) return arr.map(()=>0); return arr.map(v => (v-m)/s); }

