function std(a) { const m=mean(a); return Math.sqrt(a.reduce((s,v)=>s+(v-m)**2,0)/a.length); }
function minmax(arr) { const lo=Math.min(...arr), hi=Math.max(...arr); return arr.map(v=>(v-lo)/(hi-lo||1)); }
function cv(arr) { return std(arr)/Math.abs(mean(arr)); } // coefficient of variation

// ---- 1. Distribution Analysis ----
console.log('=== 1. 数据分布分析 ===');
console.log('');

// Appearance rank
const ranks = heroes.map(h=>h.appearanceRank);
console.log('【出场排名】');
console.log('  范围: ' + Math.min(...ranks) + ' ~ ' + Math.max(...ranks));
console.log('  均值: ' + mean(ranks).toFixed(1) + ', 标准差: ' + std(ranks).toFixed(1));
console.log('  变异系数: ' + cv(ranks).toFixed(2) + ' (均匀分布=0.58, 此值越接近均匀分布说明排名跨度好)');

// Combat power
const combats = heroes.map(h=>h.combatPower);
console.log('【战力分】');
console.log('  范围: ' + Math.min(...combats) + ' ~ ' + Math.max(...combats));
console.log('  均值: ' + mean(combats).toFixed(1) + ', 标准差: ' + std(combats).toFixed(1));
console.log('  变异系数: ' + cv(combats).toFixed(2));
// Decile analysis
const cSorted = [...combats].sort((a,b)=>a-b);
console.log('  十分位: P10='+cSorted[Math.floor(N*0.1)].toFixed(0)+' P50='+cSorted[Math.floor(N*0.5)].toFixed(0)+' P90='+cSorted[Math.floor(N*0.9)].toFixed(0));

// Win rate
const wrs = heroes.map(h=>h.winRate);
console.log('【胜率】');
console.log('  范围: ' + (Math.min(...wrs)*100).toFixed(2) + '% ~ ' + (Math.max(...wrs)*100).toFixed(2) + '%');
console.log('  均值: ' + (mean(wrs)*100).toFixed(2) + '%, 标准差: ' + (std(wrs)*100).toFixed(2) + '%');
console.log('  变异系数: ' + cv(wrs).toFixed(2));

// ---- 2. Check if data is sorted ----
console.log('');
console.log('=== 2. 数据排序检测 ===');
// Are heroes sorted by winRate in the JSON?
let wrMonotonic = true;
let wrPrev = 999;
for (const h of heroes) {
  if (h.winRate > wrPrev) { wrMonotonic = false; break; }
  wrPrev = h.winRate;
}
console.log('JSON按胜率严格降序排列: ' + (wrMonotonic ? '是 ⚠️' : '否 ✓'));

// Check if appearanceRank is just the JSON index
let arMatchesIndex = true;
for (let i = 0; i < N; i++) {
  if (heroes[i].appearanceRank !== i + 1) { arMatchesIndex = false; break; }
}
console.log('appearanceRank = JSON序号: ' + (arMatchesIndex ? '是 ⚠️' : '否 ✓'));
console.log('→ 如果两个都是\"是\"，说明原始数据就是按胜率排序后分配出场排名的，存在严重的结构冗余');

// ---- 3. Correlation Analysis ----
console.log('');
console.log('=== 3. Spearman 秩相关 ===');
function spearman(x, y) {
  const n = x.length;
  const rank = arr => { const idx = arr.map((_,i)=>i).sort((a,b)=>arr[a]-arr[b]); const r=Array(n); idx.forEach((v,i)=>r[v]=i+1); return r; };
  const rx = rank(x), ry = rank(y);
  const mx = mean(rx), my = mean(ry);
  const num = rx.reduce((s,v,i)=>s+(v-mx)*(ry[i]-my),0);
  const den = Math.sqrt(rx.reduce((s,v)=>s+(v-mx)**2,0) * ry.reduce((s,v)=>s+(v-my)**2,0));
  return num/(den||1);
}

// Compute the current algorithm scores
const aScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
const cScores = minmax(combats);
const wScores = minmax(wrs);
const rawPowers = heroes.map((h,i) => 0.20*aScores[i] + 0.50*cScores[i] + 0.30*wScores[i]);
const rMin=Math.min(...rawPowers), rMax=Math.max(...rawPowers), rRng=rMax-rMin||1;
const finalScores = rawPowers.map(v => ((v-rMin)/rRng)*100);

console.log('维度间相关 (Spearman ρ):');
console.log('  出场排名 vs 战力:  ρ = ' + spearman(ranks.map(r=>-r), combats).toFixed(4));
console.log('  出场排名 vs 胜率:  ρ = ' + spearman(ranks.map(r=>-r), wrs).toFixed(4));
console.log('  战力 vs 胜率:      ρ = ' + spearman(combats, wrs).toFixed(4));

console.log('');
console.log('finalScore 与各维度:');
const rho_app = spearman(finalScores, ranks.map(r=>r)); // ranks are smaller-is-better
const rho_com = spearman(finalScores, combats);
const rho_wr = spearman(finalScores, wrs);
console.log('  finalScore vs 出场排名: ρ = ' + rho_app.toFixed(4));
console.log('  finalScore vs 战力:     ρ = ' + rho_com.toFixed(4));
console.log('  finalScore vs 胜率:     ρ = ' + rho_wr.toFixed(4));

// ---- 4. Variance Decomposition ----
console.log('');
console.log('=== 4. 方差贡献分析 ===');
// How much of the final score variance comes from each dimension?
const weightedA = aScores.map(v=>v*0.20);
const weightedC = cScores.map(v=>v*0.50);
const weightedW = wScores.map(v=>v*0.30);

const varA = std(weightedA)**2;
const varC = std(weightedC)**2;
const varW = std(weightedW)**2;
// Covariance terms
const covAC = weightedA.reduce((s,v,i)=>s+(v-mean(weightedA))*(weightedC[i]-mean(weightedC)),0)/N;
const covAW = weightedA.reduce((s,v,i)=>s+(v-mean(weightedA))*(weightedW[i]-mean(weightedW)),0)/N;
const covCW = weightedC.reduce((s,v,i)=>s+(v-mean(weightedC))*(weightedW[i]-mean(weightedW)),0)/N;
const totalVar = std(rawPowers)**2;

console.log('各维度加权后方差占比:');
console.log('  出场排名(0.20): ' + (varA/totalVar*100).toFixed(1) + '%');
console.log('  战力(0.50):     ' + (varC/totalVar*100).toFixed(1) + '%');
console.log('  胜率(0.30):     ' + (varW/totalVar*100).toFixed(1) + '%');
console.log('  协方差项:       ' + ((2*(covAC+covAW+covCW))/totalVar*100).toFixed(1) + '%');
console.log('→ 理想情况：战力方差贡献应最大（反映0.50权重）');

// ---- 5. Actual effective weight ----
console.log('');
console.log('=== 5. 有效权重 vs 名义权重 ===');
// How much does each dimension actually influence the ranking?
// Use standardized regression coefficients
const zA = aScores.map(v=>(v-mean(aScores))/std(aScores));
const zC = cScores.map(v=>(v-mean(cScores))/std(cScores));
const zW = wScores.map(v=>(v-mean(wScores))/std(wScores));
const zFinal = finalScores.map(v=>(v-mean(finalScores))/std(finalScores));

// Approximate effective weight = abs(correlation) * original_weight * std(input)/std(output)
const eff_app = Math.abs(spearman(finalScores, ranks.map(r=>r))) * 0.20;
const eff_com = Math.abs(rho_com) * 0.50;
const eff_wr = Math.abs(rho_wr) * 0.30;
const sum_eff = eff_app + eff_com + eff_wr;
console.log('名义权重:  出场=20%  战力=50%  胜率=30%');
console.log('有效权重:  出场=' + (eff_app/sum_eff*100).toFixed(1) + '%  战力=' + (eff_com/sum_eff*100).toFixed(1) + '%  胜率=' + (eff_wr/sum_eff*100).toFixed(1) + '%');
console.log('→ 有效权重 = ρ × 名义权重 / 总和，反映实际排名影响力');

// ---- 6. Extreme cases: check top/bottom 10 ----
console.log('');
console.log('=== 6. 极端案例分析 ===');
const sorted = heroes.map((h,i)=>({...h, score:finalScores[i]}));
sorted.sort((a,b)=>b.score-a.score);

console.log('Top 10:');
sorted.slice(0,10).forEach((h,i) => {
  console.log('  '+(i+1)+'. '+h.name+' 排名='+h.appearanceRank+' 战力='+h.combatPower+' 胜率='+(h.winRate*100).toFixed(2)+'% 评分='+h.score.toFixed(1));
});

console.log('');
console.log('Bottom 10:');
sorted.slice(-10).reverse().forEach((h,i) => {
  console.log('  '+h.name+' 排名='+h.appearanceRank+' 战力='+h.combatPower+' 胜率='+(h.winRate*100).toFixed(2)+'% 评分='+h.score.toFixed(1));
});

// Check if any hero has a surprising rank
console.log('');
console.log('=== 7. \"异常\"英雄（战力与胜率矛盾） ===');
