console.log('战力低(≤中位)但胜率高(≥50%): ' + anomalies.filter(h=>h.winRate>=0.50).length + '人');
anomalies.filter(h=>h.winRate>=0.50).forEach(h => {
  console.log('  ' + h.name + ' 战力=' + h.combatPower + ' 胜率=' + (h.winRate*100).toFixed(2) + '% 评分=' + h.score.toFixed(1) + ' (排名#' + (sorted.indexOf(h)+1) + ')');
