const files = ['上路.json','打野.json','中路.json','下路.json','辅助.json'];
const allNames = [];
files.forEach(f => {
  const data = JSON.parse(fs.readFileSync('E:/kaifa/英雄排行/MOBA游戏梯度/lolm/' + f, 'utf8'));
  data.forEach(h => {
    if (!allNames.includes(h.heroName)) allNames.push(h.heroName);
  });
});

const missing = allNames.filter(n => !icons.has(n));
const extra = [...icons].filter(n => !allNames.includes(n) && n !== 'H_S_10100');

console.log('去重英雄总数: ' + allNames.length);
console.log('图标文件总数: ' + icons.size);
console.log('缺少图标的英雄: ' + missing.length + (missing.length ? ' ⚠️' : ' ✅'));
if (missing.length) missing.slice(0,5).forEach(n => console.log('  - ' + n));
console.log('未使用的图标: ' + extra.length + (extra.length ? ' (可能是多名称或备用)' : ''));
